gbfu(){return"\u0644\u0627 \u064a\u062a\u0631\u0643 \u0623\u062d\u062f \u0645\u0643\u0627\u0646\u0647. \u0647\u064a\u0627\u060c \u0625\u0644\u0649 \u0627\u0644\u0645\u0644\u0639\u0628."},
gbfn(){return"\u0627\u0644\u0639\u0628\u0648\u0627 \u0628\u0630\u0643\u0627\u0621\u060c \u0648\u0644\u0627 \u062a\u062a\u062e\u0644\u0648\u0627 \u0639\u0646 \u0628\u0639\u0636\u0643\u0645. \u0647\u064a\u0627 \u0628\u0646\u0627."},
