gbfm(){return"\u0644\u0627 \u0645\u062c\u0627\u0644 \u0644\u0627\u0644\u062a\u0642\u0627\u0637 \u0627\u0644\u0623\u0646\u0641\u0627\u0633! \u0647\u064a\u0627 \u064a\u0627 \u0634\u0628\u0627\u0628!"},
gbfp(){return"\u0647\u064a\u0627! \u0623\u0631\u0648\u0647\u0645 \u0645\u0646 \u0623\u0646\u062a\u0645!"},
